package com.nigson.commerce.fulfillment;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.*;
import com.nigson.commerce.inventory.InventoryAuthority;
import com.nigson.commerce.platform.*;
import com.nigson.shared.security.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
/** Source cancellation intent/dispatch exclusion and authenticated truth; no provider HTTP here. */
public final class CarrierCancellationService {
 private final JdbcTemplate jdbc;private final JdbcShipmentRepository shipments;private final InventoryAuthority authority;private final PlatformStore commands;private final AuditWriter audit;private final FulfillmentPolicy policy;private final Clock clock;private final TransactionTemplate read;
 public CarrierCancellationService(JdbcTemplate jdbc,JdbcShipmentRepository shipments,InventoryAuthority authority,PlatformStore commands,AuditWriter audit,FulfillmentPolicy policy,PlatformTransactionManager manager,Clock clock){this.jdbc=jdbc;this.shipments=shipments;this.authority=authority;this.commands=commands;this.audit=audit;this.policy=policy;this.clock=clock;read=new TransactionTemplate(manager);read.setReadOnly(true);read.setTimeout(3);}
 private void limits(){jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");}
 private java.sql.Timestamp stamp(Instant at){return java.sql.Timestamp.from(at);}
 private void staff(ActorAssertion.Actor actor,boolean mutation){authority.require(actor);if(mutation)ActorAssertion.recentMfa(actor,clock);}
 private CarrierCancellationValues.View view(UUID id){var rows=jdbc.queryForList("SELECT c.*,s.version AS shipment_version FROM commerce.carrier_cancellation c JOIN commerce.shipment s ON s.id=c.shipment_id WHERE c.id=?",id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var row=rows.getFirst();return new CarrierCancellationValues.View(id,(UUID)row.get("shipment_id"),row.get("state").toString(),((Number)row.get("version")).longValue(),((Number)row.get("shipment_version")).longValue(),CarrierCancellationValues.safeError(row.get("error_code")));}
 public CarrierCancellationValues.View get(ActorAssertion.Actor actor,UUID shipment){staff(actor,false);ApiValues.uuid(shipment==null?null:shipment.toString());return read.execute(s->{limits();var ids=jdbc.query("SELECT id FROM commerce.carrier_cancellation WHERE shipment_id=? ORDER BY created_at DESC,id DESC LIMIT 1",(r,n)->r.getObject(1,UUID.class),shipment);if(ids.isEmpty())throw new Problem.Failure(ProblemCode.NOT_FOUND);return view(ids.getFirst());});}
 public CarrierCancellationValues.View request(ActorAssertion.Actor actor,UUID shipment,long expected,String reason,String key,UUID correlation){staff(actor,true);ApiValues.uuid(shipment==null?null:shipment.toString());ApiValues.uuid(correlation==null?null:correlation.toString());CarrierReconciliationValues.requireReason(reason);ApiValues.idempotencyKey(key);if(expected<0||expected==Long.MAX_VALUE)throw ApiValues.invalid();var response=commands.executeLocal(actor.party().toString(),"API-197",key,EventCodec.JSON.valueToTree(Map.of("shipment",shipment,"version",expected,"reason",reason)),db->{
  limits();authority.stabilize(actor);staff(actor,true);UUID orderId=shipments.orderId(shipment);var order=shipments.order(orderId,true);var before=shipments.find(shipment,true);if(before.version()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);var row=jdbc.queryForMap("SELECT provider,provider_reference,booking_request_id,label_asset_id,dispatched_at,package_snapshot::text FROM commerce.shipment WHERE id=?",shipment);String market=jdbc.queryForObject("SELECT code FROM commerce.market WHERE id=?",String.class,order.get("market_id"));var frozen=EventCodec.JSON.readTree(row.get("package_snapshot").toString());String mode=frozen.path("mode").asString();if(!"FEDEX".equals(row.get("provider"))||!"NGN".equals(order.get("currency_code"))||!"NG".equals(market)||!Set.of("READY","EXCEPTION").contains(before.status())||row.get("dispatched_at")!=null||row.get("label_asset_id")==null||row.get("booking_request_id")==null||row.get("provider_reference")==null||!row.get("booking_request_id").toString().equals(frozen.path("bookingReference").asString())||!mode.equals(EventCodec.JSON.readTree(order.get("carrier_snapshot").toString()).path("mode").asString())||!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.shipment_event WHERE shipment_id=? AND source='FEDEX' AND status='BOOKED')",Boolean.class,shipment)))throw FulfillmentValues.rule();policy.require(mode,"FEDEX");
  var existing=jdbc.queryForList("SELECT id,booking_request_id,reference,mode FROM commerce.carrier_cancellation WHERE shipment_id=? AND state IN ('REQUESTED','QUEUED','UNKNOWN') FOR UPDATE",shipment);UUID id;if(!existing.isEmpty()){var original=existing.getFirst();if(!original.get("booking_request_id").equals(row.get("booking_request_id"))||!original.get("reference").equals(row.get("provider_reference"))||!original.get("mode").equals(mode))throw FulfillmentValues.rule();id=(UUID)original.get("id");}else{id=EventCodec.uuid7(clock.instant());Instant at=clock.instant().truncatedTo(ChronoUnit.MICROS);var command=new CarrierCancellationValues.Command(id,shipment,(UUID)row.get("booking_request_id"),row.get("provider_reference").toString(),mode,at);jdbc.update("INSERT INTO commerce.carrier_cancellation(id,created_by,updated_by,shipment_id,booking_request_id,reference,mode,reason,request_hash,requested_at,next_attempt_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)",id,actor.party().toString(),actor.party().toString(),shipment,command.bookingRequestId(),command.reference(),mode,reason,CarrierCancellationValues.hash(command),stamp(at),stamp(at));}
  audit.append(actor.party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.QUEUE_REPLAY,AuditValues.Resource.SHIPMENT,shipment,correlation,AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("version",before.version()),null);return new PlatformStore.Response(202,EventCodec.JSON.valueToTree(Map.of("id",id)),id);
 });staff(actor,true);return read.execute(s->view(ApiValues.uuid(response.body().path("id").asString())));}
 public CarrierCancellationValues.View accept(PrivateWorkload.Proof proof,CarrierCancellationValues.Receipt receipt,UUID correlation){var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-199")).findFirst().orElseThrow(ActorAssertion::denied);if(proof==null||proof.actor()!=null||!route.equals(proof.route())||!route.client().equals(proof.client())||proof.subject()==null||!proof.subject().matches("[A-Za-z0-9._:-]{1,100}"))throw ActorAssertion.denied();return verified(receipt,correlation,proof.client(),AuditValues.ActorKind.SERVICE);}
 /** Only the fixed authenticated integration reply adapter supplies this package-private path. */
 CarrierCancellationValues.View acceptRelay(CarrierCancellationValues.Receipt receipt,UUID correlation){return verified(receipt,correlation,"commerce-cancellation-relay",AuditValues.ActorKind.SYSTEM);}
 private CarrierCancellationValues.View verified(CarrierCancellationValues.Receipt input,UUID correlation,String subject,AuditValues.ActorKind kind){Objects.requireNonNull(input);policy.requireExistingMode(input.mode());ApiValues.uuid(correlation==null?null:correlation.toString());if(input.occurredAt().isAfter(clock.instant().plusSeconds(5)))throw ApiValues.invalid();commands.executeLocal("carrier-cancellation-receipt","API-199",input.commandId().toString(),EventCodec.JSON.valueToTree(input),db->{
  limits();UUID orderId=shipments.orderId(input.shipmentId());shipments.order(orderId,true);var before=shipments.find(input.shipmentId(),true);var rows=jdbc.queryForList("SELECT * FROM commerce.carrier_cancellation WHERE id=? FOR UPDATE",input.cancellationId());if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var row=rows.getFirst();var binding=jdbc.queryForMap("SELECT provider,provider_reference,booking_request_id,created_at,dispatched_at FROM commerce.shipment WHERE id=?",input.shipmentId());if(!input.shipmentId().equals(row.get("shipment_id"))||!input.bookingRequestId().equals(row.get("booking_request_id"))||!input.mode().equals(row.get("mode"))||!input.reference().equals(row.get("reference"))||!"FEDEX".equals(binding.get("provider"))||!input.bookingRequestId().equals(binding.get("booking_request_id"))||!input.reference().equals(binding.get("provider_reference")))throw FulfillmentValues.rule();String prior=row.get("state").toString();if(Set.of("CANCELLED","REJECTED").contains(prior)){if(!prior.equals(input.state())&&!input.state().equals("UNKNOWN"))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(Map.of("id",input.cancellationId())),input.cancellationId());}
  boolean cancelled=input.state().equals("CANCELLED");if(cancelled&&(Set.of("SHIPPED","DELIVERED").contains(before.status())||binding.get("dispatched_at")!=null||input.occurredAt().plusSeconds(5).isBefore(((java.sql.Timestamp)binding.get("created_at")).toInstant())))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);boolean changed=cancelled&&!before.status().equals("CANCELLED");if(changed){jdbc.update("UPDATE commerce.shipment SET status='CANCELLED',version=version+1,updated_at=?,updated_by=? WHERE id=?",stamp(clock.instant()),subject,input.shipmentId());jdbc.update("INSERT INTO commerce.shipment_event(id,created_by,shipment_id,source,event_key,status,occurred_at) VALUES (?,?,?,'FEDEX',?,'CANCELLED',?)",EventCodec.uuid7(clock.instant()),subject,input.shipmentId(),input.commandId().toString(),stamp(input.occurredAt()));shipments.progress(orderId,subject);var after=shipments.find(input.shipmentId(),false);var event=new LinkedHashMap<String,Object>();event.put("event_id",EventCodec.uuid7(clock.instant()));event.put("event_type","shipment.changed.v1");event.put("schema_version",1);event.put("producer","commerce");event.put("occurred_at",clock.instant());event.put("aggregate_id",after.id());event.put("aggregate_version",after.version());event.put("organization_id",shipments.organization(orderId));event.put("correlation_id",correlation);event.put("traceparent",null);event.put("payload",Map.of("shipment_id",after.id(),"order_id",orderId,"status","CANCELLED","occurred_at",input.occurredAt()));commands.append(EventCodec.JSON.writeValueAsString(event),subject);}
  jdbc.update("UPDATE commerce.carrier_cancellation SET state=?,accepted_at=COALESCE(accepted_at,?),lease_until=NULL,last_result_command_id=?,error_code=?,next_attempt_at=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",input.state(),stamp(clock.instant()),input.commandId(),input.reasonCode().equals("NONE")?null:input.reasonCode(),stamp(clock.instant().plusSeconds(900)),stamp(clock.instant()),subject,input.cancellationId());audit.append(subject,kind,AuditValues.Action.SHIPMENT_PROVIDER_RESULT,AuditValues.Resource.SHIPMENT,input.shipmentId(),correlation,AuditValues.Reason.VERIFIED_PROVIDER,Map.of("version",row.get("version")),Map.of("version",((Number)row.get("version")).longValue()+1),null);return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(Map.of("id",input.cancellationId())),input.cancellationId());
 });return read.execute(s->view(input.cancellationId()));}
}
